func unitDialogID(unit view.BuildingUnitView, add bool) string {
	if add {
		return "unit-add"
	}
	return "unit-" + unit.ID
}
func unitDialogTitle(add bool) string {
	if add {
		return "Einheit hinzufügen"
	}
	return "Einheit bearbeiten"
}
func unitDialogButton(add bool) string {
	if add {
		return "Einheit anlegen"
	}
	return "Änderungen speichern"
}
func unitDialogDetail(unit view.BuildingUnitView, add bool) string {
	if add {
		return "Stammdaten und Zuordnungen an einem Ort erfassen."
	}
	return unit.Label + " · " + unit.UnitTypeLabel
}
func unitShareValue(unit view.BuildingUnitView, add bool) string {
	if add {
		return "0"
	}
	return unit.ShareValue
}

